<script>
export default {
  props: {
    protocolForm: {
      type: Object,
      default: () => ({}),
    },
    channelForm: {
      type: Object,
      default: () => ({}),
    },
    source_id: {
      type: Number,
    },
  },
  data() {
    function validate(rule, value, callback) {
      const port = parseInt(value, 10);
      console.log(port, "port");

      let isPort = Number.isInteger(port) && port >= 0 && port <= 256;
      if (!isPort) {
        callback(new Error("请输入0-256范围内的数"));
      } else {
        callback();
      }
    }
    return {
      channelInfo: {},
      protocolInfo: {},
      rules: {
        instrument_number: [
          {
            required: true,
            message: "请输入",
            trigger: ["blur", "change"],
          },
          { validator: validate, trigger: ["blur", "change"] },
        ],
      },
      active: 0,
      autoAddVisible: false,
      deviceList: [],
      IPloading: true,
      ipParams: {
        page: 1,
        size: 10,
      },
      ipTotal: 0,
      pollingTimer: null,

      channelList: [],
      interfaceList: [],
      baudrateList: [2400, 4800, 9600, 19200, 38400, 57600, 115200],
      typeItem: {},
      typeList: [
        {
          value: "0001",
          name: "无线一体化负荷",
        },
        {
          value: "0002",
          name: "无线压力",
        },
        {
          value: "0003",
          name: "	无线温度",
        },
        {
          value: "0004",
          name: "无线电量",
        },
        {
          value: "0005",
          name: "无线角位移",
        },
        {
          value: "0006",
          name: "无线载荷",
        },
        {
          value: "0007",
          name: "无线扭矩",
        },
        {
          value: "0008",
          name: "无线动液面",
        },
        {
          value: "0009",
          name: "计量车",
        },
        {
          value: "000B",
          name: "无线压力温度一体化变送器",
        },
        {
          value: "1f00",
          name: "控制器(RTU)设备",
        },
        {
          value: "1f10",
          name: "手操器",
        },
        {
          value: "4000",
          name: "自定义",
          customize: true,
          range: "0x2000~0x4000",
        },
        {
          value: "2000",
          name: "无线死点开关",
        },
        {
          value: "3000",
          name: "无线拉线位移校准传感器",
        },
        {
          value: "3001",
          name: "无线拉线位移功图校准传感器",
        },
      ],
    };
  },
  created() {
    for (let i = 11; i <= 26; i++) {
      this.channelList.push(i);
    }
    this.channelInfo = {};
    this.protocolInfo = {
      ...this.protocolForm,
    };
    this.typeItem.value = this.protocolInfo.instrument_type;
    // this.getInterfaceList();
  },
  methods: {
    // getInterfaceList() {
    //   this.$api.get("/collect/getSerialPortList").then((res) => {
    //     this.interfaceList = res.data.data;
    //   });
    // },
    // submitChannel(formName) {
    //   // this.active = 1;
    //   this.$refs[formName].validate((valid) => {
    //     if (valid) {
    //       this.$api
    //         .post("/collect/setChannelConfig", {
    //           id: this.source_id,
    //           channel_config: this.channelInfo,
    //         })
    //         .then(() => {
    //           this.active = 1;
    //         });
    //     } else {
    //       return false;
    //     }
    //   });
    // },
    submitProtocol(formName) {
      this.protocolInfo.instrument_type = this.typeItem.value;
      this.$refs[formName].validate((valid) => {
        if (valid) {
          this.$api
            .post("/collect/setProtocolConfig", {
              id: this.source_id,
              protocol_config: this.protocolInfo,
            })
            .then(() => {
              this.$parent.goBack();
              this.$message.success("操作成功");
            });
        } else {
          return false;
        }
      });
    },
  },
};
</script>

