<template>
  <div class="d-center column m-10">
    <el-steps :active="active" style="width: 50%" finish-status="success">
      <el-step title="配置通道参数"></el-step>
      <el-step title="配置协议参数"></el-step>
    </el-steps>
    <el-form
      :model="channelInfo"
      :rules="rules"
      ref="channelInfo"
      label-width="120px"
      class="mt-20"
      size="small"
      v-show="active == 0"
      style="width: 40%"
    >
      <el-form-item label="地址:" prop="ip">
        <el-input v-model="channelInfo.address" style="width: 60%" />
      </el-form-item>
      <el-form-item label="端口:" prop="port">
        <el-input-number v-model="channelInfo.port"></el-input-number>
      </el-form-item>
      <el-form-item label="令牌:" prop="token">
        <el-input v-model="channelInfo.token" type="textarea"></el-input>
      </el-form-item>
      <el-form-item>
        <el-button size="small" @click="submitChannel('channelInfo')"
          >下一步</el-button
        >
      </el-form-item>
    </el-form>
    <el-form
      v-if="active == 1"
      :model="protocolInfo"
      :rules="rules"
      ref="protocolInfo"
      label-width="140px"
      class="mt-20"
      size="small"
    >
      <el-form-item label="采集间隔时间(秒):" prop="interval">
        <el-input-number v-model="protocolInfo.interval"></el-input-number>
      </el-form-item>
      <el-form-item label="超时时间(秒):" prop="timeout">
        <el-input-number v-model="protocolInfo.timeout"></el-input-number>
        （秒）
      </el-form-item>
      <el-form-item>
        <el-button size="small" @click="active = 0">上一步</el-button>
        <el-button size="small" @click="submitProtocol('protocolInfo')"
          >提交</el-button
        >
      </el-form-item>
    </el-form>
  </div>
</template>

<script>
export default {
  props: {
    protocolForm: {
      type: Object,
      default: () => ({}),
    },
    channelForm: {
      type: Object,
      default: () => ({}),
    },
    source_id: {
      type: Number,
    },
  },
  data() {
    return {
      channelInfo: {},
      protocolInfo: {},
      rules: {},
      active: 0,
      autoAddVisible: false,
      deviceList: [],
      IPloading: true,
      ipParams: {
        page: 1,
        size: 10,
      },
      ipTotal: 0,
      pollingTimer: null,
    };
  },
  created() {
    this.channelInfo = {
      ...this.channelForm,
      port: this.channelInfo.port || 8123,
    };
    this.protocolInfo = {
      ...this.protocolForm,
      timeout: this.protocolForm.timeout || 30,
      interval: this.protocolForm.interval || 10,

    };
  },
  methods: {
    submitChannel(formName) {
      // this.active = 1;
      this.$refs[formName].validate((valid) => {
        if (valid) {
          this.$api
            .post("/collect/setChannelConfig", {
              id: this.source_id,
              channel_config: this.channelInfo,
            })
            .then(() => {
              this.active = 1;
            });
        } else {
          return false;
        }
      });
    },
    submitProtocol(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          this.$api
            .post("/collect/setProtocolConfig", {
              id: this.source_id,
              protocol_config: this.protocolInfo,
            })
            .then(() => {
              this.$parent.goBack();
              this.$message.success("操作成功");
              // this.getDataSource();
            });
        } else {
          return false;
        }
      });
    },
  },
};
</script>

<style lang="scss" scoped></style>
